const dictionaries: Record<Language, Dictionary> = { nl, en, fr, de };

interface LanguageContextValue {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (key: TranslationKey | string, variables?: Record<string, string | number>) => string;
  languageInfo: (typeof languages)[number];
}

const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({
  children,
  initialLanguage,
}: {
  children: ReactNode;
  initialLanguage?: Language;
}) {
  const [language, setLanguageState] = useState<Language>(initialLanguage || "nl");

  useEffect(() => {
    if (initialLanguage) {
      setLanguageState(initialLanguage);
      return;
    }
    const saved = window.localStorage.getItem("cannix-language") as Language | null;
    if (saved && languages.some((item) => item.value === saved)) setLanguageState(saved);
  }, [initialLanguage]);

  useEffect(() => {
    const info = languages.find((item) => item.value === language) || languages[0];
    document.documentElement.lang = info.htmlLang;
    window.localStorage.setItem("cannix-language", language);
  }, [language]);

  const value = useMemo<LanguageContextValue>(() => ({
    language,
    setLanguage: (next) => setLanguageState(next),
    languageInfo: languages.find((item) => item.value === language) || languages[0],
    t: (key, variables) => {
      let text = (dictionaries[language] as Record<string, string>)[key] || (nl as Record<string, string>)[key] || key;
      Object.entries(variables || {}).forEach(([name, replacement]) => {
        text = text.replaceAll(`{${name}}`, String(replacement));
      });
      return text;
    },
  }), [language]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used within LanguageProvider");
  return context;
}

export const getTranslatedPair = (value: string, language: Language) => {
  const [title, description] = value.split("|");
  return { title: title || "", description: description || "" };
};
